select ea.id as id, ea.user_id as user_id,ea.answer_id as answer_id, ea.evaluation_id as evaluation_id, ea.create_time as create_time, ea.update_time as update_time, mhe.result_description as result_description,mhe.daily_advice as daily_advice,mhe.professional_advice as professional_advice from evaluation_answer ea left join mental_health_evaluation mhe on ea.evaluation_id = mhe.id
and ea.user_id = #{evaluationAnswer.userId}
limit #{pageable.offset}, #{pageable.pageSize}

select
  id, answer_id, evaluation_id, create_time, update_time, user_id
from evaluation_answer


        and id = #{id}


        and answer_id = #{answerId}


        and evaluation_id = #{evaluationId}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and user_id = #{userId}


limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from evaluation_answer


        and id = #{id}


        and answer_id = #{answerId}


        and evaluation_id = #{evaluationId}


        and create_time = #{createTime}


        and update_time = #{updateTime}


        and user_id = #{userId}
